 <style>
 :root{--primary:<?= $escape($primary) ?>;--secondary:<?= $escape($secondary) ?>;--ink:#14202d;--muted:#607181;--soft:#f4f7f9}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--ink);background:#fff;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}a{color:inherit}.shell{width:min(76rem,calc(100% - 2rem));margin:auto}.top{position:sticky;z-index:30;top:0;border-bottom:1px solid #e5eaed;background:rgb(255 255 255 / 94%);backdrop-filter:blur(12px)}.nav{display:flex;align-items:center;justify-content:space-between;min-height:4.8rem;gap:1rem}.brand{display:flex;align-items:center;gap:.8rem;text-decoration:none;font-size:1.05rem;font-weight:850}.brand img{width:9rem;height:3rem;object-fit:contain;object-position:left center}.links{display:flex;align-items:center;gap:1.15rem}.links a{text-decoration:none;font-weight:700}.button{display:inline-flex;align-items:center;justify-content:center;min-height:2.9rem;padding:.72rem 1.1rem;border:0;border-radius:.72rem;color:#fff;background:var(--primary);text-decoration:none;font:inherit;font-weight:850;cursor:pointer;box-shadow:0 .45rem 1rem color-mix(in srgb,var(--primary) 20%,transparent)}.hero{position:relative;overflow:hidden;padding:7rem 0 6rem;background:linear-gradient(135deg,color-mix(in srgb,var(--secondary) 94%,#000),var(--secondary));color:#fff}.hero:after{content:"";position:absolute;width:38rem;height:38rem;right:-12rem;top:-16rem;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--primary) 70%,transparent),transparent 68%)}.hero-content{position:relative;z-index:1;max-width:49rem}.eyebrow{margin:0 0 .7rem;color:var(--primary);font-weight:900;text-transform:uppercase;letter-spacing:.1em}.hero .eyebrow{color:color-mix(in srgb,var(--primary) 55%,#fff)}.hero h1{max-width:47rem;margin:0;font-size:clamp(2.5rem,6vw,4.9rem);line-height:1.02;letter-spacing:-.05em}.hero p{max-width:42rem;margin:1.2rem 0 1.8rem;color:#e8eef5;font-size:1.18rem;line-height:1.7}.banners{padding:2rem 0 0}.banner-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:1rem}.banner{position:relative;grid-column:span 6;min-height:15rem;overflow:hidden;border-radius:1.1rem;color:#fff;background:#1d2e43}.banner:first-child:last-child{grid-column:1/-1;min-height:22rem}.banner img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.banner:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgb(5 15 28 / 85%),rgb(5 15 28 / 15%))}.banner-copy{position:relative;z-index:2;display:flex;flex-direction:column;align-items:flex-start;justify-content:end;width:min(32rem,90%);min-height:inherit;padding:2rem}.banner-copy h2{margin:0;font-size:clamp(1.7rem,3vw,2.7rem)}.banner-copy p{margin:.6rem 0 1rem;line-height:1.55}.section{padding:5rem 0}.section.soft{background:var(--soft)}.section-head{display:flex;align-items:end;justify-content:space-between;gap:1rem;margin-bottom:2rem}.section h2{margin:.25rem 0;font-size:clamp(2rem,4vw,3rem);letter-spacing:-.035em}.section-head p,.about p{color:var(--muted);line-height:1.75}.courses{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.course{display:flex;flex-direction:column;min-height:20rem;padding:1.35rem;border:1px solid #e0e6ea;border-radius:1rem;background:#fff;box-shadow:0 .5rem 1.6rem rgb(28 48 68 / 7%)}.course-icon{display:grid;place-items:center;width:2.8rem;height:2.8rem;border-radius:.8rem;color:var(--primary);background:color-mix(in srgb,var(--primary) 9%,#fff);font-size:1.25rem}.course h3{margin:1.1rem 0 .5rem;font-size:1.25rem}.course p{margin:0 0 1rem;color:var(--muted);line-height:1.55}.course-bottom{display:grid;gap:.8rem;margin-top:auto}.course-price{font-weight:900;font-size:1.2rem;color:var(--secondary)}.course-price small{display:block;margin-top:.2rem;color:var(--muted);font-size:.78rem;font-weight:600}.course .button{width:100%}.about{display:grid;grid-template-columns:.8fr 1.2fr;gap:4rem;align-items:start}.about-mark{padding:2rem;border-radius:1.2rem;color:#fff;background:linear-gradient(145deg,var(--primary),color-mix(in srgb,var(--primary) 70%,var(--secondary)))}.about-mark strong{display:block;font-size:3rem}.contact{display:flex;align-items:center;justify-content:space-between;gap:2rem;padding:2rem;border-radius:1.2rem;background:var(--secondary);color:#fff}.contact h2{margin:0}.contact p{margin:.5rem 0 0;color:#dfe8f2}.contact-links{display:flex;flex-wrap:wrap;gap:.7rem}.contact-links a{display:inline-flex;align-items:center;min-height:2.7rem;padding:.6rem .9rem;border:1px solid rgb(255 255 255 / 35%);border-radius:.65rem;color:#fff;text-decoration:none;font-weight:750}.footer{padding:2rem 0;color:var(--muted);border-top:1px solid #e4e9ec}.footer-row{display:flex;justify-content:space-between;gap:1rem}.preview{position:fixed;z-index:50;right:1rem;bottom:1rem;padding:.55rem .8rem;border-radius:999px;color:#704d00;background:#fff1bd;border:1px solid #e6ca65;font-size:.78rem;font-weight:850}@media(max-width:900px){.links a:not(.button){display:none}.courses{grid-template-columns:repeat(2,minmax(0,1fr))}.about{grid-template-columns:1fr;gap:1.5rem}}@media(max-width:650px){.courses{grid-template-columns:1fr}.banner{grid-column:1/-1}.hero{padding:5rem 0 4rem}.section{padding:3.5rem 0}.section-head,.footer-row,.contact{align-items:flex-start;flex-direction:column}.brand span{display:none}}
