<header class="top"><nav class="shell nav"><a class="brand" href="<?= $escape($publicBase) ?>#inicio"><?php if ($logo !== ''): ?><img src="<?= $escape($assetBasePath . $logo) ?>" alt="<?= $escape($siteTitle) ?>"><?php else: ?><span><?= $escape($siteTitle) ?></span><?php endif; ?></a><div class="links"><a href="<?= $escape($publicBase) ?>#cursos">Cursos</a><?php foreach (($site['pages'] ?? []) as $page): ?><?php if ((int) ($page['show_in_menu'] ?? 0) === 1): ?><a href="<?= $escape($publicBase) ?>/p/<?= $escape($page['slug']) ?>"><?= $escape($page['title']) ?></a><?php endif; ?><?php endforeach; ?><a href="<?= $escape($publicBase) ?>#contato">Contato</a><a class="button" href="<?= $escape($publicBase) ?>#cursos"><?= $store ? 'Comprar curso' : 'Ver catálogo' ?></a></div></nav></header>
<main>
 <section class="hero" id="inicio"><div class="shell hero-content"><p class="eyebrow"><?= $escape($siteTitle) ?></p><h1><?= $escape((string) $site['hero_title']) ?></h1><p><?= $escape((string) $site['hero_text']) ?></p><a class="button" href="#cursos"><?= $store ? 'Escolher meu curso' : 'Conhecer os cursos' ?></a></div></section>
 <?php if (($site['banners'] ?? []) !== []): ?><section class="banners"><div class="shell banner-grid"><?php foreach ($site['banners'] as $banner): ?><article class="banner"><img src="<?= $escape($publicBase) ?>/banner/<?= (int) $banner['id'] ?>" alt="<?= $escape($banner['title']) ?>"><div class="banner-copy"><h2><?= $escape($banner['title']) ?></h2><?php if (!empty($banner['subtitle'])): ?><p><?= $escape($banner['subtitle']) ?></p><?php endif; ?><?php if (!empty($banner['cta_label']) && !empty($banner['cta_url'])): ?><a class="button" href="<?= $escape($banner['cta_url']) ?>"><?= $escape($banner['cta_label']) ?></a><?php endif; ?></div></article><?php endforeach; ?></div></section><?php endif; ?>
 <section class="section soft" id="cursos"><div class="shell"><header class="section-head"><div><p class="eyebrow">Formações</p><h2>Cursos em destaque</h2><p>Escolha a formação que combina com o seu próximo objetivo.</p></div></header>
 <?php if (($site['products'] ?? []) === []): ?><div class="course"><span class="course-icon">✦</span><h3>Catálogo em preparação</h3><p>Novas formações serão publicadas em breve. Entre em contato para receber atendimento.</p></div><?php else: ?><div class="courses"><?php foreach ($site['products'] as $product): ?><article class="course"><span class="course-icon">✦</span><h3><?= $escape($product['name']) ?></h3><p><?= $escape($product['description'] ?? 'Formação disponível nesta unidade.') ?></p><div class="course-bottom"><span class="course-price">R$ <?= number_format((float) $product['value'], 2, ',', '.') ?><?php if ((int) $product['max_installments'] > 1): ?><small>em até <?= (int) $product['max_installments'] ?>x</small><?php endif; ?></span><a class="button" href="<?= $escape($publicBase) ?>/curso/<?= (int) $product['id'] ?>"><?= $store ? 'Ver curso e comprar' : 'Conhecer o curso' ?></a></div></article><?php endforeach; ?></div><?php endif; ?>
 </div></section>
 <section class="section" id="sobre"><div class="shell about"><aside class="about-mark"><small>Conhecimento que transforma</small><strong><?= $escape($siteTitle) ?></strong></aside><div><p class="eyebrow">Institucional</p><h2><?= $escape((string) ($site['about_title'] ?: 'Sobre nós')) ?></h2><p><?= nl2br($escape((string) $site['about_text'])) ?></p></div></div></section>
 <section class="section" id="contato"><div class="shell contact"><div><h2>Vamos conversar?</h2><p>Fale com nossa equipe e encontre o curso ideal.</p></div><div class="contact-links"><?php if ($whatsapp !== ''): ?><a href="https://wa.me/<?= $escape($whatsapp) ?>" target="_blank">WhatsApp</a><?php endif; ?><?php if (!empty($site['contact_email'])): ?><a href="mailto:<?= $escape($site['contact_email']) ?>">E-mail</a><?php endif; ?><?php if (!empty($site['instagram_url'])): ?><a href="<?= $escape($site['instagram_url']) ?>" target="_blank">Instagram</a><?php endif; ?><?php if (!empty($site['facebook_url'])): ?><a href="<?= $escape($site['facebook_url']) ?>" target="_blank">Facebook</a><?php endif; ?></div></div></section>
</main>
